import React, { useEffect, useState } from "react";
import Store from './store';
import devStore from "@/store/dev";
import styles from './index.module.less';
import { Button, Collapse, Divider, Drawer, Link, List, Message, Space, Tag, Tree, TreeSelect } from "@arco-design/web-react";
import { IconSettings } from "@arco-design/web-react/icon";
import { useHistory } from "react-router-dom";
import { useObserver } from "mobx-react-lite";
import config from "config";
import userStore from "@code/store/user";
import AppTheme from "@/components/Settings/theme";
import { PermissionAuth } from "@/components/Permission";
import i18next from "i18next";



export const settingStore = Store;



const Settings = () => {

    const [store] = useState(() => new Store());


    return useObserver(() => {

        const history = useHistory();
        const { visible, setVisible, hidden, setHidden, userList } = store;
        const { pathname } = history.location
        useEffect(() => {
            if(!userStore.isLogin && !store.isOne){
                if(pathname.indexOf('/admin') == 0){
                    store.changeLogin("admin").then((res) => {
                        Message.success("已自动登陆超级管理员账户")
                    })
                }
            }
        },[pathname])

        const userInfo = userStore.info;
        // console.log('devStore', devStore, userStore.info, toJS(devStore.routes))
    
        if(hidden) return null;
    
        return (
            <React.Fragment>
                <div className={styles['fixed-settings']}>
                    <Button icon={<IconSettings />} type="primary" size="large" 
                        onClick={() => {
                            setVisible(true)
                        }}
                    />
                </div>
                <Drawer
                    width={500}
                    title="功能预览"
                    visible={visible}
                    onCancel={() => {
                        setVisible(false)
                    }}
                    className={styles.drawer}
                    footer={(
                        <Space>
                            <Button
                                onClick={() => {
                                    setHidden(true)
                                }}
                            >不再展示</Button>
                            <Button
                                onClick={() => {
                                    setVisible(false)
                                }}
                            >关闭</Button>
                        </Space>
                    )}
                >
                <Collapse
                    bordered={false}
                    defaultActiveKey={['1', '2']}
                    style={{ maxWidth: 1180 }}
                >
                    <Collapse.Item header='切换登陆账户' name='1'>
                        <List
                            dataSource={userList}
                            bordered={false}
                            render={(item, index) => {
                                const isLogin = userInfo?.login_name == item.login_name;
                                return (
                                    <List.Item key={index}>
                                        <Space>
                                            <span>{item.login_name}</span>
                                            {item.user_name? <span>({item.user_name})</span> : null}
                                            {isLogin?  
                                                <Tag color="arcoblue">已登陆</Tag> 
                                                : <Button size="mini" type="primary" shape="round"
                                                    onClick={() => {
                                                        store.changeLogin(item.login_name)
                                                    }}
                                                >登陆</Button>
                                            }
                                        </Space>
                                    </List.Item>
                                )
                            }}
                        />
                    </Collapse.Item>
                    <Collapse.Item header="路由导航" name="2">
                        <Tree
                            blockNode
                            autoExpandParent
                            fieldNames={{
                                key: "key",
                                title: "name"
                            }}
                            onSelect={(keys, extra) => {
                                const { dataRef: item }: any = extra.node.props
                                history.push(item.path);
                            }}
                            treeData={devStore.routes}
                            renderTitle={({ title, dataRef, ...props }) => {
                                return i18next.t(title as string)
                            }}
                        />
                        <Divider style={{ margin: "0 20px" }}>后台路由</Divider>
                        <Tree
                            blockNode
                            autoExpandParent
                            fieldNames={{
                                key: "path",
                                title: "name"
                            }}
                            onSelect={(keys, extra) => {
                                const { dataRef: item }: any = extra.node.props
                                if(item.path == "/login"){
                                    history.push(`${keys[0]}`);
                                }else {
                                    history.push(`${config.manage_path}${keys[0]}`);
                                }
                            }}
                            treeData={[
                                {
                                    path: "/login",
                                    name: "登陆页面"
                                },
                                ...devStore.adminRoutes,
                            ]}
                            renderTitle={({ title, dataRef, ...props }) => {
                                return i18next.t(title as string)
                            }}
                        />
                    </Collapse.Item>
                    <Collapse.Item header="主题预览" name="3">
                        <AppTheme />
                    </Collapse.Item>
                    <PermissionAuth authKeys={['dev.setting']}>
                        <Collapse.Item header="开发配置" name="4">
                        
                        </Collapse.Item>
                    </PermissionAuth>
                </Collapse>
                </Drawer>
            </React.Fragment>
        )

    })

}


export default Settings;